-- Queer Atlas: Turin venue, event and service intelligence
-- Run after city-turin-curated-v1.sql. Researched and checked 2026-08-14.

begin;

with researched as (
 select * from jsonb_to_recordset($turin_place_intel$
[
 {"name":"Nora Book & Coffee","patch":{"queue_wait":"Morning coffee is normally simple; a Friday presentation or book launch can fill the small room and dehors quickly. Arrive fifteen to twenty minutes before a named talk if sitting matters. There is no club-style door, but limited tables mean lingering regulars shape capacity.","best_nights":"Nora is strongest by day and around its reading or presentation calendar, often toward the end of the week. Choose a quiet breakfast to browse properly, or a listed literary night to meet people. It is not a substitute for dancing later.","crowd_mix":"Queer and transfeminist locals, students, writers, neighbourhood coffee regulars and informed visitors. Reviews suggest the room feels naturally queer rather than tourist-staged; older solo guests may find the younger crowd initially noticeable, though the social tone is broadly warm.","dress_code":"Whatever works for a cafe, from workday basics to expressive queer style. No door code. Bring a tote if the independent shelves are likely to tempt you.","staff_inclusivity":"The identity is structural: a transfeminist catalogue, marginalised voices, groups and accessible upgrades sit inside the business model. Most recent reviews praise kind service. Allergy handling has drawn one specific criticism, so communicate dietary risk directly.","review_signal":"A strong 4.6-scale review consensus repeatedly mentions safety, books, plants, coffee and friendly staff. The useful dissent concerns bathroom or general upkeep and possible dairy cross-contamination, not the queer welcome. Treat food-allergy needs more cautiously than ordinary vegan preference.","source_urls":["https://compravicino.comune.torino.it/epic/nora-book-coffee/","https://wanderlog.com/place/details/5882765/nora-book--coffee","https://www.tripadvisor.it/Restaurant_Review-g187855-d11928340-Reviews-Nora_Book_Coffee-Turin_Province_of_Turin_Piedmont.html"],"research_status":"official_profile_plus_large_current_review_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"CasArcobaleno and Barcolbaleno","patch":{"queue_wait":"Listening desks and groups use their own appointments or registration; public social nights may create a small bar queue. The bigger friction is arriving for the wrong function, not a velvet rope. Read whether the activity is open, booked or membership-based before leaving.","best_nights":"Choose the exact group, game night, presentation or community event that matches you. A busy Barcolbaleno evening is easiest for casual conversation; a service appointment is deliberately quieter and should not be treated as social nightlife.","crowd_mix":"Association volunteers, queer locals across generations and identities, newcomers, activists, service users and friends. The crowd changes sharply with the host group, making the calendar a better predictor than weekday.","dress_code":"No aesthetic test. Everyday clothes, political tees, office wear and expressive looks coexist. Respect any scent, masking or quiet-space request attached to a specific gathering.","staff_inclusivity":"Consent language, a quiet red room, service access and multiple member associations make inclusion operational. The bar's card requirement can surprise international visitors, but it is an association rule rather than a selective nightclub door; ask which card is accepted.","review_signal":"Public review volume is modest but positive, while the official space description offers unusually concrete evidence about consent and access. Community recommendations consistently point newcomers here for groups and connection. Judge each hosted activity separately rather than scoring the whole house as one bar.","source_urls":["https://casarcobaleno.it/gli-spazi/","https://www.arcigaytorino.it/","https://www.reddit.com/r/torino/comments/1f19sio/community_lgbt_torino_come_conoscere_gente/"],"research_status":"official_operation_plus_local_community_signal","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Centralino Club","patch":{"queue_wait":"The Pride party and established Friday formats can produce a real late queue. Admission reports are inconsistent, so arriving around doors with the correct event information is safer than joining at peak time after midnight. Keep ticket terms and ID ready and maintain an alternative plan.","best_nights":"Only a named queer night: the official Pride party is verified, while weekly identities can change. Friday is the strongest recurring signal in current listings. Do not infer that an ordinary opening offers the same crowd or welcome.","crowd_mix":"On queer editions: Torinesi, students, pop and techno dancers, Pride visitors and international guests across several rooms. Locals remain important at the door; review complaints suggest tourists sometimes experience the admission culture differently.","dress_code":"Smart-casual to clubwear generally fits, but no stable official dress code was found. The practical code is event fit, valid ID and a composed door approach. A refusal should not be read as a verdict on personal expression—use the backup venue.","staff_inclusivity":"Hosting Torino Pride provides meaningful community evidence, and positive guests praise security and staff. That sits beside repeated allegations of inconsistent or discriminatory tourist treatment. Queer branding does not erase those accounts; document a serious incident and share it with the organiser.","review_signal":"Current aggregation is weak-to-mixed, around 3.0 across hundreds of reviews. Good music, energy and security appear alongside high-price, opaque-door and service complaints. Centralino can deliver a major Turin night, but it is the package's clearest example of why venue intelligence must include dissent.","source_urls":["https://qlist.app/venues/Torino/Club-Switchboard/dXRHeTYyY3pSdDhUOWFuVnRXMExmdw","https://www.torinopride.it/facebook-event/torino-pride-official-party/"],"research_status":"verified_queer_programme_plus_large_mixed_review_consensus","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Nasty Club","patch":{"queue_wait":"Bananamia draws the Friday rush after midnight, and the courtyard does not eliminate pressure at security or cloakroom. A May 2026 inspection documented severe overcapacity, so arrive closer to doors, identify exits and do not stay in a density that prevents easy movement.","best_nights":"Friday for Bananamia is the queer reason to go; other Nasty nights are mainstream or student-led. Follow the current Bananamia announcement because the party has changed homes across its long history. Earlier arrival gives more room before the second-room peak.","crowd_mix":"A broad, youthful LGBTQ+ and allied Turin crowd, students, pop and reggaeton groups and some visitors. It is less identity-specific than a small community bar and can feel like a large city club wearing a distinctly queer Friday programme.","dress_code":"Night-out casual, denim, colour, glamour and practical dancewear all work; no fetish or formal code is published for Bananamia. Wear shoes that manage a crowded two-room floor and outdoor courtyard.","staff_inclusivity":"The decades-old queer promoter relationship is meaningful, but access and safety also depend on the venue operator. The 2026 capacity violation is a concrete failure of crowd management. Raise access questions with the promoter before buying and treat visible congestion as a live safety issue.","review_signal":"Current listings like the two rooms, courtyard and party energy; local posts confirm Bananamia remains socially relevant. The police finding—841 people against an authorised 550—carries more weight than vague praise when assessing safety. Great energy and operational caution belong in the same verdict.","source_urls":["https://xceed.me/en/torino/venue/nasty-club","https://t.me/banana_mia","https://www.lastampa.it/torino/2026/05/23/news/controlli_movida_ogimomo_nasty_club_multe-15633517/"],"research_status":"current_promoter_and_venue_plus_official_enforcement_caveat","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"011 Sauna Club","patch":{"queue_wait":"Ordinary afternoons are usually direct; Friday and Saturday dress-code sessions become busier after 20:00, with a further shift when areas connect around midnight. Membership registration and explaining the full price can slow a first visit, so arrive before the theme peak.","best_nights":"Friday after 20:00 for naked-and-mask cruising; Saturday for the fully naked format and later energy. A weekday afternoon is calmer and more sauna-led. Choose deliberately because the same 800 square metres behaves like two different venues.","crowd_mix":"Men only: Turin regulars, regional visitors, fetish-night guests and tourists, with age and body range depending on the session. Reviews suggest regulars know one another and staff, while a newcomer may need an explicit tour.","dress_code":"Association membership is required. Friday after 20:00 is naked plus mask; Saturday after 20:00 is 100% naked. Outside those sessions towel and sauna norms apply. Phone restrictions protect privacy and should be explained without confrontation.","staff_inclusivity":"Several 2026 reviewers name exceptionally welcoming staff and a careful first-time introduction. Other guests report abrupt communication, tourist hostility or disputed re-entry. Ask about facilities, footwear, phone rules, re-entry and total charges at reception before committing.","review_signal":"The 3.9 review picture is genuinely divided: spacious labyrinth, freedom and good hosting versus cleanliness, broken equipment and staff concerns. Fresh positive reports mean the venue should not be dismissed; fresh negative operational reports mean it should not be romanticised either.","source_urls":["https://www.011saunaclub.it/","https://wanderlog.com/place/details/2454456/011-sauna-club","https://www.travelgay.com/venue/011-sauna-club"],"research_status":"official_facilities_and_rules_plus_current_mixed_reviews","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Garage Club Torino","patch":{"queue_wait":"The smaller scale rarely creates a long visible queue, but membership setup and uncertain same-day operation are the friction points. A recent visitor reported being refused while online hours showed open. Confirm directly before crossing town, especially outside the Friday long evening.","best_nights":"Friday's official long evening to 03:00 and buffet creates the clearest social window. Under-25 pricing can alter the age balance. Earlier weekday hours suit a quieter sauna visit, although less crowd can mean very little interaction.","crowd_mix":"Men only, often local regulars and a mixed-age crowd rather than a polished circuit audience. Reviewers who like it value an unforced, familiar atmosphere. Those seeking a huge or consistently busy international bathhouse may find the room too quiet.","dress_code":"Association entry, locker and towel norms; specific cruise themes should be checked with the club. Fashion is irrelevant. Ask whether footwear is needed and whether smoking affects any shared area if that matters to you.","staff_inclusivity":"Positive accounts describe a friendly owner and relaxed welcome, while negative ones cite rude communication or being turned away despite published hours. Same-day confirmation is not merely editorial caution here—it directly responds to the repeated operational complaint.","review_signal":"The roughly 3.3 review picture is mixed and specific: people praise layout, acceptance and sociability but criticise cold or faulty wet facilities, smoke, maintenance and schedule accuracy. Visit for its local character only after verifying the sauna and whirlpool are functioning.","source_urls":["https://www.garageclub.it/","https://wanderlog.com/it/place/details/2454454/garage-club","https://www.tripadvisor.co.uk/Attraction_Review-g187855-d23837760-Reviews-Garageclub_Torino-Turin_Province_of_Turin_Piedmont.html"],"research_status":"official_2026_hours_plus_current_mixed_reviews","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"La Boulandrola","patch":{"queue_wait":"It is a small neighbourhood room, so lunch tables can disappear even without a formal queue. Breakfast and mid-afternoon are easier for a spontaneous stop. Booking is sensible for a group; the venue closes at 20:00 and never develops a late club line.","best_nights":"There is no nightlife peak. Go for breakfast, lunch or the Piedmontese merenda-sinoira rhythm, then continue elsewhere. A community or neighbourhood event can add social energy, but should be verified rather than assumed.","crowd_mix":"San Salvario neighbours, students, politically engaged locals, vegan diners and queer visitors who recognise the room's values. The audience is mixed and local first, without a tourist-facing gay-bar performance.","dress_code":"Daytime casual, work clothes, cycling layers and expressive everyday style. No code. This is a cafe where political conversation and food matter more than being seen.","staff_inclusivity":"Recent reviewers repeatedly praise attentive, kind and politically engaged staff, and familiar queer symbols are visible. That supports a credible welcome without claiming the venue is exclusively LGBTQ+. Wheelchair-accessible entry is also listed by current directories.","review_signal":"The current 4.6 consensus highlights service, relaxed personality, coffee, wine and vegan products. A few reviews find food inconsistent or the small space uncomfortable. It is strongest as a warm local pause, not as a destination restaurant or scene anchor.","source_urls":["https://www.arteaporte.com/host/la-boulandrola/","https://restaurantguru.it/La-Boulandrola-caffe-cucina-e-bottega-Turin","https://www.tripadvisor.it/Restaurant_Review-g187855-d27821879-Reviews-La_Boulandrola-Turin_Province_of_Turin_Piedmont.html"],"research_status":"current_hours_plus_recent_food_and_welcome_reviews","updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Bunker","patch":{"queue_wait":"Equi.Voci required free registration, and large music events can create separate security flow. Arrive before the listed start if a workshop or talk has limited capacity. An ordinary empty address tells you nothing because Bunker is programme-led.","best_nights":"Choose a verified queer or inclusion-led programme such as Equi.Voci, not a random weekend. Afternoon offers discussion and participation; evening brings performance and DJs. The host organisation matters as much as the industrial site.","crowd_mix":"On Equi.Voci: queer youth, disability and access advocates, multicultural organisations, artists, speakers and a broad younger public. Other Bunker programmes can draw entirely different music or neighbourhood audiences.","dress_code":"Practical clothes for a raw industrial site, changing temperature and indoor-outdoor movement. Expressive party looks fit the evening, but accessibility and comfort matter more than polish.","staff_inclusivity":"The 2026 programme built gender equality, LGBTQ+ youth wellbeing, multiculturality and accessible cities into content. That is strong event-level evidence. It should not be projected onto every future promoter without checking their access plan.","review_signal":"Official municipal documentation is stronger here than generic venue reviews because Bunker's function changes by event. The useful signal is scale, youth focus and free registered access. Review the organiser, transport and accessibility details for each date.","source_urls":["https://eventi.comune.torino.it/calendario/equi-voci-all-freaks-free/"],"research_status":"official_event_level_inclusion_verified","updated_at":"2026-08-14T00:00:00Z"}}
]
$turin_place_intel$) r(name text,patch jsonb)
)
update public.places p set venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||r.patch,updated_at=timezone('utc',now()) from researched r
where lower(trim(p.city))='turin' and lower(trim(p.name))=lower(trim(r.name));

with researched as (
 select * from jsonb_to_recordset($turin_event_intel$
[
 {"name":"Lovers Film Festival 2026","patch":{"entry_wait":"Each screening used its own cinema ticket; opening and guest sessions carried the highest pressure. Online sales closed fifteen minutes before the film, while reduced tickets were handled at Cinema Massimo.","best_arrival":"Collect a reduced ticket early or arrive thirty minutes before a high-profile premiere. Build the day around one film strand and leave room for discussions rather than stacking incompatible sessions.","crowd_mix":"Queer cinema audiences, filmmakers, critics, students, activists, local regulars and international festival visitors across generations.","dress_code":"Cinema casual; opening night supports a sharper look but imposes no general code.","host_inclusivity":"More than fifty films from twenty-one countries and a festival history built against queer stereotypes make representation central, not decorative.","source_urls":["https://www.loversff.com/","https://eventi.comune.torino.it/calendario/lovers-film-festival/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Equi.Voci - All Freaks Free 2026","patch":{"entry_wait":"Free entry required registration; individual workshops or activities could still reach capacity inside the larger site.","best_arrival":"Before 15:00 for the participatory afternoon, or before the 20:00 transition if performance and DJs are the priority.","crowd_mix":"Younger queer people, artists, disability advocates, multicultural communities, educators and a broad public interested in practical inclusion.","dress_code":"Comfortable indoor-outdoor layers and personal expression; no aesthetic gate.","host_inclusivity":"The event directly programmed minority stress, gender equality, citizenship and accessible-city questions, making access part of its editorial structure.","source_urls":["https://eventi.comune.torino.it/calendario/equi-voci-all-freaks-free/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Torino Pride 2026","patch":{"entry_wait":"Free march without ticketing; density built at Parco del Valentino before the 15:30 departure and again around the Piazza Vittorio stage.","best_arrival":"Around 14:15 for orientation before the 14:30 gathering. Use the announced quieter or seated options rather than forcing the centre of the procession.","crowd_mix":"Turin associations, activists, families, students, elders, drag and nightlife communities, allies and regional and international visitors.","dress_code":"Walking shoes, water, sun or rain protection and any Pride expression that survives a long central route. Glass was prohibited.","host_inclusivity":"Quiet spaces, a seated access bus, Red Cross support, water, earplugs, LIS interpretation, accessible stage space and free rapid testing were explicitly published.","source_urls":["https://www.torinopride.it/pride/pride-2026/","https://www.comune.torino.it/novita/notizie/torino-pride-2026"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Torino Pride Official Party 2026","patch":{"entry_wait":"No presale or guest list meant a first-come door. The lower price before 22:00 encouraged an early wave; late arrivals needed to expect a club queue.","best_arrival":"20:30-21:30 for lower entry, food and easier orientation before the full post-march rush.","crowd_mix":"Marchers, Torino Pride volunteers, local club crowds, visitors and people using the quiet or companion-access provisions.","dress_code":"Pride looks, dancewear and comfortable post-march clothes all fit; no special code was published.","host_inclusivity":"An accessible route, quiet zone, earplugs and companion discount were concrete additions, while all proceeds supported the Pride organisation.","source_urls":["https://www.torinopride.it/facebook-event/torino-pride-official-party/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Bananamia Fridays - August 2026","patch":{"entry_wait":"Friday pressure rises after midnight. Buy or register through the live promoter route if offered, and arrive earlier if two-room crowding makes you uncomfortable.","best_arrival":"Around 23:30 gives time to learn the rooms and courtyard before the peak. Verify which August Friday is active on the day.","crowd_mix":"Young LGBTQ+ Torinesi, students, pop and reggaeton groups, long-time Bananamia followers and visiting friends.","dress_code":"Expressive night-out casual rather than a fixed theme; follow any special-edition announcement.","host_inclusivity":"A queer party running since 1991 carries real community recognition, but the host venue's recent capacity violation requires independent safety judgement.","source_urls":["https://t.me/banana_mia","https://xceed.me/en/torino/venue/nasty-club","https://www.lastampa.it/torino/2026/05/23/news/controlli_movida_ogimomo_nasty_club_multe-15633517/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Supermedium - Festival delle Colline Torinesi 2026","patch":{"entry_wait":"Fixed-seat €15 festival performance; advance booking is sensible for the Italian premiere and the smaller of two dates.","best_arrival":"Thirty minutes before the 21:00 Saturday or 17:00 Sunday performance, allowing time for Teatro Astra access and ticket collection.","crowd_mix":"Contemporary dance audiences, queer and feminist culture followers, artists, students and festival visitors.","dress_code":"Theatre casual; no formal requirement. Choose comfort for a concentrated contemporary-dance work.","host_inclusivity":"Eight female or non-binary performers and a work about bodies carrying multiple identities make gender plurality intrinsic to the stage language.","source_urls":["https://www.fondazionetpe.it/festival/supermedium/","https://www.fondazionetpe.it/festival-delle-colline-torinesi/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"EuroPride Torino 2027","patch":{"entry_wait":"The detailed 2027 access system is not yet published. The final march will be public, while concerts, conferences and parties may use separate registration or ticketing.","best_arrival":"Book accommodation well before June 2027, then build the week from the official programme once venues and access provisions are released.","crowd_mix":"Turin's local community and organisations alongside Pride delegations, activists, performers, institutions and visitors from across Europe.","dress_code":"No universal code across a nine-day citywide programme; prepare separately for marches, civic events, culture and nightlife.","host_inclusivity":"The organising framework is rights-led and city-supported, but accessibility must be judged from the final venue-by-venue plan rather than assumed today.","source_urls":["https://www.europride2027.eu/en/","https://www.torinogiovani.it/salute-e-vita-affettiva/comunita-lgbtqia-e-orientamenti/europride-torino-2027"],"updated_at":"2026-08-14T00:00:00Z"}}
]
$turin_event_intel$) r(name text,patch jsonb)
)
update public.events e set event_intel=coalesce(e.event_intel,'{}'::jsonb)||r.patch,updated_at=timezone('utc',now()) from researched r
where lower(trim(e.city))='turin' and lower(trim(e.name))=lower(trim(r.name));

with researched as (
 select * from jsonb_to_recordset($turin_service_intel$
[
 {"name":"Maurice GLBTQ","patch":{"booking_lead_time":"Library visits can follow public hours; peer groups, anti-discrimination support and individual help use the current calendar or direct contact. Email first for a sensitive or complex need.","best_time":"Name whether you need community, migration support, trans peer connection, discrimination help or library research so Maurice can route the first conversation properly.","client_mix":"LGBTQIA+ people across generations, trans and non-binary people, migrants and refugees, researchers, volunteers and people seeking connection rather than crisis care.","preparation":"Bring relevant documents only for a practical case. Ask about language, confidentiality, accessibility and whether a peer or professional route fits the need.","provider_inclusivity":"Founded in 1985 and built around queer peer groups, specialist collections and rights work, Maurice's competence is institutional and community-held.","source_urls":["https://www.mauriceglbtq.org/","https://www.comune.torino.it/argomenti/integrazione-sociale/tematiche-lgbt"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"Pronto Arcigay Torino","patch":{"booking_lead_time":"Friday sessions are appointment-only by email. Write ahead rather than arriving at CasArcobaleno and expecting an immediate confidential conversation.","best_time":"Use the first email to state the broad topic and urgency without disclosing more than necessary; staff can then direct family, work, asylum or identity questions.","client_mix":"People questioning or navigating orientation and gender identity, relatives, workers facing acceptance issues, newcomers and asylum seekers affected by SOGI persecution.","preparation":"Ask what the volunteers can provide, what requires a lawyer or clinician, and whether language or accessibility support can be arranged.","provider_inclusivity":"Professionally trained volunteers and explicit asylum support make this more than a social welcome desk, while its scope remains listening and referral.","source_urls":["https://www.arcigaytorino.it/servizi/sportello-accoglienza/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"SanArcobaleno","patch":{"booking_lead_time":"Sessions are periodic and may use registration or a final arrival cut-off. Check the exact date; routine testing should not be confused with urgent post-exposure treatment.","best_time":"Arrive early in the listed window and tell the clinician the exposure timing and anatomical sites so tests and follow-up are appropriate.","client_mix":"Queer community members and others seeking anonymous, free HIV and syphilis testing in a low-threshold environment.","preparation":"Know when the possible exposure occurred and current medication. Ask about test windows, other STI sites, results and referral; seek urgent PEP care immediately after a recent high-risk exposure.","provider_inclusivity":"Delivering anonymous testing inside CasArcobaleno through community and health partners reduces institutional friction and makes queer competence visible.","source_urls":["https://www.arcigaytorino.it/","https://www.torinopride.it/pride/pride-2026/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"TO Housing","patch":{"booking_lead_time":"Email starts an assessment; placement depends on vulnerability, eligibility and one of twenty-four spaces becoming available. It cannot promise immediate emergency accommodation.","best_time":"Contact as soon as housing risk becomes clear and involve a social service or trusted organisation where possible; do not wait until the final safe night.","client_mix":"LGBTQI+ youth expelled by family, migrants and refugees, trans people, isolated elders and others facing severe housing and social vulnerability.","preparation":"Use a safe email, explain immediate risk and referral context, and ask how personal data and location confidentiality are protected. Never travel to a protected residence uninvited.","provider_inclusivity":"The housing model was designed specifically around LGBTQI+ exclusion and combines shelter with reintegration rather than offering a generic bed under rainbow branding.","source_urls":["https://www.quore.org/to-housing-accoglienza-lgbtqi/","https://www.quore.org/contatti/"],"updated_at":"2026-08-14T00:00:00Z"}},
 {"name":"CIDIGeM Torino","patch":{"booking_lead_time":"Initial contact is email only and community accounts describe long or unpredictable waits. Request confirmation, keep a record and ask what to do if an appointment is cancelled.","best_time":"Start early, before prescriptions or documents become urgent. Use Maurice or another peer organisation for navigation and support while waiting, without presenting peer help as clinical substitution.","client_mix":"Adults with gender incongruence seeking multidisciplinary public care, with a linked pathway for minors through Regina Margherita.","preparation":"Summarise goals, current care, medication and existing reports. Ask exactly which stage, documents and specialists apply and how follow-up communication works.","provider_inclusivity":"It is the regional expert public centre and provides important clinical pathways, but repeated reports of delay and difficult communication mean institutional specialism should not be described as effortless lived access.","source_urls":["https://www.torinogiovani.it/luoghi/cidigem-centro-interdipartimentale-disforia-di-genere-molinette","https://www.cittadellasalute.to.it/index.php?Itemid=53&catid=57&id=211%3Aotorinolaringoiatria-audiologia-e-foniatria-u&option=com_content&showall=1&view=article","https://www.reddit.com/r/askTransgender_Italy/comments/1bdwd3h/consigli_per_psicologi_per_iniziare_tos/"],"updated_at":"2026-08-14T00:00:00Z"}}
]
$turin_service_intel$) r(name text,patch jsonb)
)
update public.services s set service_intel=coalesce(s.service_intel,'{}'::jsonb)||r.patch,updated_at=timezone('utc',now()) from researched r
where lower(trim(s.city))='turin' and lower(trim(s.name))=lower(trim(r.name));

commit;

select 'places_with_complete_intel' check_name,count(*) result from public.places where lower(trim(city))='turin' and coalesce(venue_intel->>'queue_wait','')<>'' and coalesce(venue_intel->>'best_nights','')<>'' and coalesce(venue_intel->>'crowd_mix','')<>'' and coalesce(venue_intel->>'dress_code','')<>'' and coalesce(venue_intel->>'staff_inclusivity','')<>''
union all select 'events_with_complete_intel',count(*) from public.events where lower(trim(city))='turin' and coalesce(event_intel->>'entry_wait','')<>'' and coalesce(event_intel->>'host_inclusivity','')<>''
union all select 'services_with_complete_intel',count(*) from public.services where lower(trim(city))='turin' and coalesce(service_intel->>'booking_lead_time','')<>'' and coalesce(service_intel->>'provider_inclusivity','')<>''
order by check_name;
